			preview.textContent = selectedOptions.length ? selectedOptions.slice(0, 3).map((option) => option.label).join("、") + (selectedOptions.length > 3 ? ` 等 ${selectedOptions.length} 项` : "") : "尚未选择";
			button.textContent = selectedOptions.length ? "修改" : "选择";
