	var tryQuickBuy = async (context = {}, item, options = {}) => {
		const { suppressNotifications = false } = options;
		const notify = (message, type) => {
			if (!suppressNotifications) showNotification(message, type);
		};
		const buttonRoot = context?.quickBuyButton ? context.quickBuyButton.__root || context.quickBuyButton : null;
		try {
			const baselinePrice = Number(getPrice(item));
			if (!Number.isFinite(baselinePrice) || baselinePrice <= 0) {
				notify("No cached price available", UINotificationType.NEGATIVE);
				return {
					success: false,
					reason: "noCachedPrice"
				};
			}
			const listing = await fetchLivePlayerPrice(item);
			const listingPrice = Number(listing?._auction?.buyNowPrice);
			if (!Number.isFinite(listingPrice) || listingPrice <= 0) {
				notify("No active listing found", UINotificationType.NEGATIVE);
				return {
					success: false,
					reason: "noListing"
				};
			}
			const lowestPrice = listingPrice;
			const priceLabel = lowestPrice.toLocaleString();
			if (buttonRoot?.setAttribute) buttonRoot.setAttribute("title", `Quick Buy @${priceLabel}`);
			if (lowestPrice > baselinePrice) {
				notify(`Lowest listing (${priceLabel}) exceeds expected price (${baselinePrice.toLocaleString()})`, UINotificationType.NEGATIVE);
				return {
					success: false,
					reason: "priceAboveBaseline",
					price: lowestPrice,
					priceLabel,
					baseline: baselinePrice,
					baselineLabel: baselinePrice.toLocaleString()
				};
			}
			const definitionId = Number(listing?.definitionId || item?.definitionId || 0);
			const auctionId = Number(listing?._auction?.tradeId || listing?._auction?.id || listing?.id || 0);
			const success = (await executeFcxEaRequest(() => services.Item.bid(listing, lowestPrice), "购买转会市场球员", {
				scope: "Price",
				verifyAfterFailure: async () => {
					try {
						if ((await fetchUnassigned()).some((candidate) => Number(candidate?.definitionId || 0) === definitionId)) return {
							state: "applied",
							value: {
								success: true,
								status: 200
							}
						};
						services.Item.clearTransferMarketCache();
						const criteria = new UTBucketedItemSearchViewModel().searchCriteria;
						criteria.type = ItemType.PLAYER;
						criteria.definitionId = definitionId;
						criteria.maxBuy = lowestPrice;
						const result = await executeFcxEaRequest(() => services.Item.searchTransferMarket(criteria, 1), "核验转会市场购买状态", {
							scope: "Price",
							ignoreCancellation: true
						});
						return (result?.data?.items || result?.response?.items || []).some((candidate) => Number(candidate?._auction?.tradeId || candidate?._auction?.id || candidate?.id || 0) === auctionId) ? { state: "not_applied" } : {
							state: "unknown",
							reason: "购买结果无法确认，为避免重复扣费未自动重试"
						};
					} catch (error) {
						return {
							state: "unknown",
							reason: `购买状态核验失败：${error?.message || error}`
						};
					}
				}
			}))?.success !== false;
			if (success) try {
				await dealWithUnassigned();
			} catch (err) {
				console.error("dealWithUnassigned error", err);
			}
			notify(success ? `Quick buy success at ${priceLabel}` : "Quick buy failed", success ? UINotificationType.POSITIVE : UINotificationType.NEGATIVE);
			return {
				success,
				reason: success ? "success" : "bidFailed",
				price: lowestPrice,
				priceLabel
			};
		} catch (error) {
			console.error("Quick buy error", error);
			notify("Quick buy encountered an error", UINotificationType.NEGATIVE);
			return {
				success: false,
				reason: "error",
				error
			};
		}
	};
