				appendTaskHistoryCardLine(card, "small", "", `提交 ${submissions} 次 · 开包 ${record.summary?.packsOpened || 0} 个 · 挑选 ${record.summary?.picksCompleted || 0} 次 · 获得 ${players} 名球员`);
