			basic: counts.basic,
			plus: counts.plus,
			maxed: counts.basic >= PLAYSTYLE_ACADEMY_CONFIG.limits.basic && counts.plus >= PLAYSTYLE_ACADEMY_CONFIG.limits.plus,
