				let content = "";
				try {
					content = String(window.getComputedStyle(icon, "::before")?.content || "").replaceAll("\"", "").replaceAll("'", "").trim();
				} catch (_error) {
					content = "";
				}
				icon.classList.toggle("has-glyph", Boolean(content && content !== "none" && content !== "normal"));
