			reportOperationStatus("EVO", "正在校验球员与 PlayStyle 状态");
			const latest = (await fetchPlayers()).find((player) => academyPlayerId(player) === facts.id);
			if (!latest) throw new Error("球员已不在俱乐部，请刷新列表后重试");
			if (academySnapshotSignature(latest) !== expectedSignature) throw new Error("球员 PlayStyle 状态已经变化，请重新打开后再应用");
			const currentCounts = readPlayStyleCounts(latest, PLAYSTYLE_ACADEMY_CONFIG);
