		createNumberSpinner(parent, "快速出售总评阈值", "packQuickSellUnder", 0, 99, getSettings(0, 0, "packQuickSellUnder"), (spinner) => saveSettings(0, 0, "packQuickSellUnder", spinner.getValue()));
