					options: factories.DataProvider.getItemRarityDP({
						itemSubTypes: [ItemSubType.PLAYER],
						itemTypes: [ItemType.PLAYER],
						quality: SearchLevel.ANY,
						tradableOnly: false
					}).filter((entry) => entry.id > 0 && !entry.label.includes("*")).map((entry) => ({
						value: entry.label,
						label: entry.label,
						iconUrl: getShellUri(entry.id, entry.id < 4 ? ItemRatingTier.GOLD : ItemRatingTier.NONE)
					})),
